GRANT ALL ON TABLE pgmq.q_events_rsvp TO app_user, api_key;


-- Queue access for the application role. The app runs domain-table DML as
-- `app_user` (SET LOCAL ROLE in the query/command layers) and the event
-- triggers enqueue into these queues as the invoking role. pgmq.send builds
-- its INSERT dynamically (plpgsql EXECUTE ... RETURNING), which checks both
-- INSERT and SELECT on the queue table, and the msg_id identity sequence is
-- only accessed as the table owner. pgmq 1.5+ does not install with PUBLIC
-- queue grants, and the role does not exist yet when this migration usually
-- runs — grant on current and future queues via default privileges; the SET
-- ROLE grant itself comes from the project's api-key management migration.
DO $$
BEGIN
    IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'app_user') THEN
        EXECUTE format('GRANT INSERT, SELECT ON ALL TABLES IN SCHEMA pgmq TO app_user');
        EXECUTE format('ALTER DEFAULT PRIVILEGES IN SCHEMA pgmq GRANT INSERT, SELECT ON TABLES TO app_user');
    END IF;
END
$$;

-- Shared domain event emitter function.
-- Called by per-table triggers to enqueue events into pgmq.
-- Trigger args: TG_ARGV[0] = domain name, TG_ARGV[1] = table name.
CREATE OR REPLACE FUNCTION emit_domain_event() RETURNS TRIGGER AS $$
DECLARE
    p_domain TEXT := TG_ARGV[0];
    p_table_name TEXT := TG_ARGV[1];
    v_event_type TEXT;
    v_entity_id UUID;
    v_tenant_id UUID;
    v_changed_fields TEXT[];
    v_payload JSONB;
    v_queue_name TEXT;
    v_col TEXT;
BEGIN
    -- Determine event type
    CASE TG_OP
        WHEN 'INSERT' THEN
            v_event_type := 'created';
            v_entity_id := NEW.id;
        WHEN 'UPDATE' THEN
            v_event_type := 'updated';
            v_entity_id := NEW.id;
        WHEN 'DELETE' THEN
            v_event_type := 'deleted';
            v_entity_id := OLD.id;
    END CASE;

    -- Extract organization/tenant ID if present (domain tables use platform_organization_id,
    -- platform tables use tenant_id)
    IF TG_OP = 'DELETE' THEN
        IF to_jsonb(OLD) ? 'platform_organization_id' THEN
            v_tenant_id := OLD.platform_organization_id;
        ELSIF to_jsonb(OLD) ? 'tenant_id' THEN
            v_tenant_id := OLD.tenant_id;
        END IF;
    ELSE
        IF to_jsonb(NEW) ? 'platform_organization_id' THEN
            v_tenant_id := NEW.platform_organization_id;
        ELSIF to_jsonb(NEW) ? 'tenant_id' THEN
            v_tenant_id := NEW.tenant_id;
        END IF;
    END IF;

    -- Fallback: try session variable if column has zero-UUID default
    IF v_tenant_id = '00000000-0000-0000-0000-000000000000' THEN
        v_tenant_id := COALESCE(
            NULLIF(current_setting('app.organization_id', true), '')::UUID,
            v_tenant_id
        );
    END IF;

    -- Compute changed fields on UPDATE
    IF TG_OP = 'UPDATE' THEN
        v_changed_fields := ARRAY[]::TEXT[];
        FOR v_col IN SELECT key FROM jsonb_each(to_jsonb(NEW))
        LOOP
            IF to_jsonb(NEW) -> v_col IS DISTINCT FROM to_jsonb(OLD) -> v_col THEN
                v_changed_fields := array_append(v_changed_fields, v_col);
            END IF;
        END LOOP;
    END IF;

    -- Build event payload
    v_payload := jsonb_build_object(
        'event_type', v_event_type,
        'domain', p_domain,
        'entity_table', p_table_name,
        'entity_id', v_entity_id,
        'tenant_id', v_tenant_id,
        'changed_fields', to_jsonb(COALESCE(v_changed_fields, ARRAY[]::TEXT[])),
        'occurred_at', now(),
        'correlation_id', COALESCE(
            NULLIF(current_setting('app.correlation_id', true), '')::UUID,
            gen_random_uuid()
        )
    );

    -- Enqueue to domain-specific queue
    v_queue_name := 'events_' || p_domain;
    PERFORM pgmq.send(v_queue_name, v_payload);

    IF TG_OP = 'DELETE' THEN
        RETURN OLD;
    ELSE
        RETURN NEW;
    END IF;
END;
$$ LANGUAGE plpgsql;
